Below is a simple, robust TCP/IP server in C. It listens on a specified port, accepts incoming connections, forks a child process for each client (so multiple clients can be handled concurrently), echoes received data back to the client, and properly reaps child processes to avoid zombies.

Save as tcp_server.c and compile with: gcc -Wall -O2 -o tcp_server tcp_server.c

Code:

```c
/*
 * Simple TCP server (IPv4) in C
 * Usage: ./tcp_server <port>
 *
 * Features:
 * - TCP/IPv4
 * - Binds to all interfaces (INADDR_ANY)
 * - Listens and accepts connections
 * - Forks a child per client to handle concurrent clients
 * - Echoes received data back to the client
 * - Reaps child processes with SIGCHLD handler
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define BACKLOG 10      /* How many pending connections queue will hold */
#define BUF_SIZE 4096

/* SIGCHLD handler to reap terminated children */
static void sigchld_handler(int signo) {
    (void)signo;
    while (waitpid(-1, NULL, WNOHANG) > 0) { }
}

int main(int argc, char *argv[]) {
    int listen_fd, conn_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    int port;
    int opt = 1;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    port = atoi(argv[1]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    /* Install SIGCHLD handler */
    struct sigaction sa;
    sa.sa_handler = sigchld_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGCHLD, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    /* Create socket */
    listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Allow reuse of address/port */
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* Bind */
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY; /* bind to all interfaces */
    server_addr.sin_port = htons(port);

    if (bind(listen_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* Listen */
    if (listen(listen_fd, BACKLOG) == -1) {
        perror("listen");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", port);

    /* Accept loop */
    for (;;) {
        client_len = sizeof(client_addr);
        conn_fd = accept(listen_fd, (struct sockaddr *)&client_addr, &client_len);
        if (conn_fd == -1) {
            if (errno == EINTR) continue; /* interrupted by signal, retry */
            perror("accept");
            continue;
        }

        printf("Accepted connection from %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            close(conn_fd);
            continue;
        }

        if (pid == 0) {
            /* Child process */
            close(listen_fd); /* child doesn't need listening socket */

            char buf[BUF_SIZE];
            ssize_t n;

            /* Simple echo loop */
            while ((n = read(conn_fd, buf, sizeof(buf))) > 0) {
                ssize_t total_written = 0;
                while (total_written < n) {
                    ssize_t w = write(conn_fd, buf + total_written, n - total_written);
                    if (w == -1) {
                        if (errno == EINTR) continue;
                        perror("write");
                        close(conn_fd);
                        _exit(EXIT_FAILURE);
                    }
                    total_written += w;
                }
            }
            if (n == -1) perror("read");

            printf("Connection from %s:%d closed\n",
                   inet_ntoa(client_addr.sin_addr),
                   ntohs(client_addr.sin_port));

            close(conn_fd);
            _exit(EXIT_SUCCESS);
        } else {
            /* Parent process */
            close(conn_fd); /* parent doesn't need connected socket */
        }
    }

    /* Close listening socket (unreachable in this code) */
    close(listen_fd);
    return 0;
}
```

Notes and possible improvements:
- This is a basic concurrent server using fork. For high performance or many connections consider using an event-driven model (select/poll/epoll) or a thread pool.
- For IPv6 support, use getaddrinfo() and accept both IPv4/IPv6.
- Add application-level protocol handling rather than simple echoing as needed.

